shots.draw_js:
clearScene();setBig(null);setEq(null);
note("手上只有轨迹",640,280,"b lg");
note("没有奖励，也没有模型",640,350,"r lg");
setCap("专家轨迹到手了。<b>接下来学什么？</b>这里有三条不同的路。");

clearScene();setEq(null);
setBig("都是从示范里学","叫法不同而已，差别不大");
setCap("三条路学的是<b>三个不同的对象</b>，可迁移性差别很大。");

clearScene();setBig(null);setEq(null);
note("行为克隆：直接学 π",360,260,"b lg","start");
note("逆强化学习：学 R",360,340,"g lg","start");
note("学徒学习：学 R 再规划",360,420,"v lg","start");
setCap("三条路：<b>学 π</b> · <b>学 R</b> · <b>学 R 然后用它规划出 π</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"学到 π",sub:"动力学一变就失效",state:"dead"},
  {label:"学到 R",sub:"换环境仍可重新规划",state:"on"},
  {label:"代价",sub:"R 更难学，且不唯一",state:"dead"}]});
note("差别在可迁移性",640,420,"y");
setCap("<b>奖励比策略更可迁移</b>：策略绑在动力学上，奖励不绑。");

clearScene();setBig(null);setEq(null);
note("学 π：快，但绑在动力学上",360,290,"b lg","start");
note("学 R：慢，但编码的是意图",360,370,"g lg","start");
setCap("<b>指名反驳</b>：三条路学的是三个对象，选择取决于<b>你要不要迁移</b>。");

clearScene();setBig(null);
setEq("$$\\{(s_1,a_1),(s_2,a_2),\\ldots\\}\\ \\longrightarrow\\ \\text{supervised learning}$$","top");
note("状态当输入，动作当标签",640,310,"b lg");
setCap("行为克隆没有任何新东西：<b>它就是一个分类（或回归）问题</b>。");

clearScene();setEq(null);
setBig("那误差界直接能用","监督学习的理论都是现成的");
setCap("监督学习的保证有一个<b>前提</b>，而那个前提在 MDP 里会被打破。");

clearScene();setBig(null);setEq(null);
note("训练分布：专家去过的状态",360,280,"g lg","start");
note("测试分布：你自己会到的状态",360,360,"r lg","start");
setCap("训练数据来自<b>专家的</b>状态分布，而你要在<b>自己的</b>状态分布上工作。");

clearScene();setBig(null);setEq(null);
mdpChain({n:5,y:280,r:26,x:340,gap:150,
  label:function(i){return i<2?"✓":"?";},
  cls:function(i){return i<2?"g":"r";},
  arcs:[[0,1,"","g",0],[1,2,"一次错","r",0],[2,3,"","r",0],[3,4,"","r",0]]});
note("从这里起没有数据",640,392,"r");
setCap("一次错误就把你推出专家的分布，<b>之后的每一步都在没有数据的区域里</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"不是过拟合",sub:"训练分布上可以完美",state:"on"},
  {label:"是分布偏移",sub:"被推到分布之外",state:"dead"},
  {label:"而且自我强化",sub:"越偏越没数据",state:"dead"}]});
note("这是 MDP 特有的",640,420,"y");
setCap("<b>指名反驳</b>：监督学习的保证是<b>同分布</b>的，而 MDP 让你自己走出那个分布。");

clearScene();setBig(null);
setEq("$$\\varepsilon=0.01,\\qquad T=100$$","top");
note("每步错 1%",640,300,"b lg");
note("整条轨迹代价多少",640,360,"y lg");
setCap("每步 1% 的错误率，跑 100 步。<b>总代价是多少？</b>");

clearScene();setEq(null);
setBig("εT = 1 次错","1% 乘 100 步，就这么简单");
setCap("这是<b>监督学习</b>的算法 —— 它默认每一步的错误<b>互不影响</b>。");

clearScene();setBig(null);
setEq("$$J(\\pi)-J(\\pi^*)\\;\\le\\;\\varepsilon\\sum_{t=1}^{T}(T-t+1)\\;=\\;\\varepsilon\\,\\frac{T(T+1)}{2}$$","top");
note("第 t 步错 → 毁掉 T−t+1 步",640,310,"r lg");
setCap("一次错误的代价不是 1，是<b>剩下的整条轨迹</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2],step:620,vals:[5.5,15.5,50.5],
  x:380,y:430,w:520,h:170,max:55,
  label:function(i){return ["T=10","T=30","T=100"][i];},
  cls:function(i){return i===2?"r":"v";},
  fmt:function(v){return "×"+v.toFixed(1);}});
note("放大倍数 = (T+1)/2",640,466,"r");
setCap("实际代价是监督直觉的多少倍：<b>T=100 时 50.5 倍</b>。");

clearScene();setBig(null);setEq(null);
note("O(εT)",400,290,"g lg");
note("O(εT²)",880,290,"r lg");
note("差的是阶，不是倍数",640,400,"y lg");
setCap("<b>指名反驳</b>：εT 与 εT² 差的是<b>阶</b>。把 ε 减半救不了它。");
